-- Temporada de LaLiga con equipos provisionales, como la que sembraban las migraciones V33.1 y V34 antiguas.
-- Idempotente: se puede ejecutar antes de cada test aunque la base sea compartida.


SELECT setval('teams_id_seq', GREATEST((SELECT max(id) FROM teams), 1));
SELECT setval('matches_id_seq', GREATEST((SELECT max(id) FROM matches), 1));
